package ru.neverland.townytreasury.data;
import org.bukkit.configuration.*;
import org.bukkit.configuration.file.YamlConfiguration;
import ru.neverland.townytreasury.model.*;
import java.util.*;
import java.nio.file.*;
import java.nio.channels.FileChannel;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.io.IOException;
public final class TreasuryRepository {
    private final Path file;private volatile Map<UUID,CityLedger> cities=Map.of();private boolean writable;
    public TreasuryRepository(Path file){this.file=file;}public Map<UUID,CityLedger> cities(){return cities;}
    public void load()throws Exception{writable=false;if(!Files.exists(file)){cities=Map.of();writable=true;return;}var y=new YamlConfiguration();y.load(file.toFile());if(number(y,"schema")!=1)throw new IOException("Неверная схема казны");var root=section(y,"cities");var next=new HashMap<UUID,CityLedger>();for(String id:root.getKeys(false)){var p=section(root,id);Map<Budget,Long> funds=new EnumMap<>(Budget.class);Map<Budget,Integer> shares=new EnumMap<>(Budget.class);for(var b:Budget.values()){funds.put(b,number(p,"funds."+b.id()));shares.put(b,Math.toIntExact(number(p,"shares."+b.id())));}Map<String,Week> weeks=new HashMap<>();var w=section(p,"weeks");for(String key:w.getKeys(false)){var v=section(w,key);Map<Budget,Long> categories=new EnumMap<>(Budget.class);for(var b:Budget.values())categories.put(b,number(v,"categories."+b.id()));weeks.put(key,new Week(values(section(v,"income")),values(section(v,"expenses")),categories,number(v,"refunds"),number(v,"adjustments"),values(section(v,"production")),bool(v,"production-known")));}
        CityLedger.Pending pending=null;if(p.contains("pending")){var v=section(p,"pending");pending=new CityLedger.Pending(UUID.fromString(v.getString("id")),number(v,"at"),number(v,"amount"),Budget.parse(v.getString("category")),v.getString("source"),v.getString("reason"));}
        Object history=p.get("history");if(!(history instanceof List<?> list)||list.stream().anyMatch(v->!(v instanceof String)))throw new IOException("Неверная история бюджета");next.put(UUID.fromString(id),new CityLedger(number(p,"balance"),bool(p,"enabled"),funds,shares,number(p,"revision"),number(p,"started"),Objects.requireNonNull(p.getString("notified")),weeks,pending,p.getStringList("history")));}cities=Map.copyOf(next);writable=true;}
    private static ConfigurationSection section(ConfigurationSection p,String key)throws IOException{var v=p.getConfigurationSection(key);if(v==null)throw new IOException("Отсутствует раздел: "+key);return v;}
    private static boolean bool(ConfigurationSection p,String key)throws IOException{if(!(p.get(key) instanceof Boolean v))throw new IOException("Неверный флаг: "+key);return v;}
    private static long number(ConfigurationSection p,String key)throws IOException{try{return new java.math.BigDecimal(String.valueOf(p.get(key))).longValueExact();}catch(Exception ex){throw new IOException("Неверное число: "+key,ex);}}
    private static Map<String,Long> values(ConfigurationSection p)throws IOException{var out=new HashMap<String,Long>();for(String key:p.getKeys(false))out.put(key,number(p,key));return out;}
    public void put(UUID town,CityLedger city)throws IOException{var next=new HashMap<>(cities);next.put(town,city);replace(next);}
    public void replace(Map<UUID,CityLedger> next)throws IOException{if(!writable)throw new IOException("Запись запрещена до успешной загрузки казны");next=Map.copyOf(next);if(next.equals(cities))return;var y=new YamlConfiguration();y.set("schema",1);y.createSection("cities");for(var entry:next.entrySet()){String k="cities."+entry.getKey()+".";var c=entry.getValue();y.set(k+"balance",c.balance());y.set(k+"enabled",c.enabled());y.set(k+"revision",c.revision());y.set(k+"started",c.started());y.set(k+"notified",c.notified());y.set(k+"history",c.history());for(var b:Budget.values()){y.set(k+"funds."+b.id(),c.funds().get(b));y.set(k+"shares."+b.id(),c.shares().get(b));}y.createSection(k+"weeks");for(var entryWeek:c.weeks().entrySet()){String v=k+"weeks."+entryWeek.getKey()+".";var w=entryWeek.getValue();y.createSection(v+"income",w.income());y.createSection(v+"expenses",w.expenses());y.createSection(v+"production",w.production());y.set(v+"production-known",w.productionKnown());y.set(v+"refunds",w.refunds());y.set(v+"adjustments",w.adjustments());for(var b:Budget.values())y.set(v+"categories."+b.id(),w.categories().get(b));}if(c.pending()!=null){var p=c.pending();y.set(k+"pending.id",p.id().toString());y.set(k+"pending.at",p.at());y.set(k+"pending.amount",p.amount());y.set(k+"pending.category",p.category().id());y.set(k+"pending.source",p.source());y.set(k+"pending.reason",p.reason());}}
        Path parent=file.toAbsolutePath().getParent();Files.createDirectories(parent);Path temp=Files.createTempFile(parent,"treasury-",".tmp");try{byte[] bytes=y.saveToString().getBytes(StandardCharsets.UTF_8);try(var channel=FileChannel.open(temp,StandardOpenOption.WRITE,StandardOpenOption.TRUNCATE_EXISTING)){var buffer=ByteBuffer.wrap(bytes);while(buffer.hasRemaining())channel.write(buffer);channel.force(true);}try{Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}cities=next;}finally{Files.deleteIfExists(temp);}}
}
